// Aeve, Progenitor Ooze
// status: ready
// Storm (When you cast this spell, copy it for each spell cast before it this turn. Copies become tokens.)
// Aeve isn't legendary if it's a token.
// Aeve enters with a +1/+1 counter on it for each other Ooze you control.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_1_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (Some(asker.source).is_some_and(|candidate: ObjectId| q.state().obj(candidate).token)) && (source == affected) }
#[allow(unused_variables)] fn ability_1_0_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); chars.supertypes.legendary = false; }
#[allow(unused_variables, unused_mut)] fn ability_2_enters(g: &mut dyn Game, entering: &mut Entering) -> Result<(), Suspend> { let asker = &Asker::new(entering.object, entering.controller); let more = { let q: &dyn Query = g; ((q.state().battlefield().iter().copied().filter(|&id| (!(Target::Object(asker.source).object() == Some(id)) && q.chars(id).has_subtype(q.words(asker.source).subtype(Subtype::Ooze)) && Target::Object(asker.source).object().map(|o: ObjectId| q.controller(o)) == Some(q.controller(id)))).collect::<Vec<ObjectId>>()).len() as i64).clamp(0, 32767) as i16 }; entering.counters[CounterKind::PlusOne as usize] = entering.counters[CounterKind::PlusOne as usize].saturating_add(more);
 Ok(()) }

